/**
 * Normalized read-only indicators. Null means unavailable, NOT zero.
 * A queue record never means a publicly confirmed vacancy.
 */
export const ENGINE_IDS=['A','B','C','D','CHATGPT','GEMINI'] as const;
export type EngineId=typeof ENGINE_IDS[number];
export type EngineRole='discovery'|'documents';
export type Health='recent'|'stale'|'unreported'|'error';
export type EngineCounts={
  scheduled:number|null;attempted:number|null;useful:number|null;blocked:number|null;
  candidates:number|null;verified:number|null;queued:number|null;
  publishedConfirmed:number|null;processed:number|null;
};
export type EngineRow={id:EngineId;name:string;role:EngineRole;status:Health;
  observedAt:string|null;source:string;scope:string;notes:string[];counts:EngineCounts};
export type DayPoint={day:string;engine:EngineId;measure:'sources_attempted'|'docs_processed';value:number};
export const ENGINE_META:Record<EngineId,{name:string;role:EngineRole;freshHours:number}>={
 A:{name:'Motor A',role:'discovery',freshHours:2},
 B:{name:'Motor B',role:'documents',freshHours:8},
 C:{name:'Motor C',role:'documents',freshHours:8},
 D:{name:'Motor D',role:'discovery',freshHours:8},
 CHATGPT:{name:'Motor ChatGPT',role:'discovery',freshHours:8},
 GEMINI:{name:'Motor Gemini',role:'discovery',freshHours:9}
};
export function nonnegative(value:unknown):number|null {
 return typeof value==='number'&&Number.isSafeInteger(value)&&value>=0?value:null;
}
export function asRow(value:unknown):Record<string,unknown> {
 return value&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,unknown>:{};
}
export function stamp(value:unknown):string|null {
 if(typeof value!=='string')return null;
 const ts=Date.parse(value);return Number.isFinite(ts)?new Date(ts).toISOString():null;
}
export function health(id:EngineId,at:string|null,hasError=false,now=Date.now()):Health {
 if(hasError)return 'error';
 if(!at)return 'unreported';
 const age=now-Date.parse(at);
 if(age< -300000 || age>ENGINE_META[id].freshHours*3600_000)return 'stale';
 return 'recent';
}
export function blankCounts():EngineCounts {
 return {scheduled:null,attempted:null,useful:null,blocked:null,candidates:null,
  verified:null,queued:null,publishedConfirmed:null,processed:null};
}
export function makeRow(id:EngineId,raw:unknown,source:string,patch:Partial<EngineCounts>,
 observed:unknown,notes:string[]=[],hasError=false):EngineRow {
 const observedAt=stamp(observed);
 const counts={...blankCounts(),...patch};
 for(const [key,value] of Object.entries(counts)){
   if(value!==null&&nonnegative(value)===null)throw Error('bad_metric:'+id+':'+key);
 }
 return {id,name:ENGINE_META[id].name,role:ENGINE_META[id].role,
  status:health(id,observedAt,hasError),observedAt,source,
  scope:id==='B'||id==='C'?'documentos/cola':'fuentes y ofertas',notes,counts};
}
/* HTTP200 without anti-bot, error or render challenge: read, not a vacancy. */
export function usefulFromAudits(audits:unknown):number|null {
 if(!Array.isArray(audits))return null;
 return audits.filter(x=>{
   const r=asRow(x);return r.http===200&&r.error==null&&r.renderRequired!==true;
 }).length;
}
export function adaptEngine(id:EngineId,raw:unknown,options:{readFailed?:boolean}={}):EngineRow {
 const r=asRow(raw),hasError=options.readFailed===true;
 if(hasError) return makeRow(id,null,'lectura fallida',{},null,['Lectura fallida no equivale a cero.'],true);
 if(id==='A'){
  const s=asRow(r.summary),reads=nonnegative(s.sourcesRead),useful=usefulFromAudits(s.audits);
  return makeRow(id,raw,'free_public_source_cursor_v3',
   {attempted:reads,useful,blocked:reads!==null&&useful!==null?Math.max(0,reads-useful):null,
    candidates:nonnegative(s.noticesChecked),verified:nonnegative(s.verified),
    queued:nonnegative(s.pending),publishedConfirmed:null},
   r.checkedAt||s.checkedAt,['Fuente leída no equivale a empleo; origen de publicación sin conciliación.']);
 }
 if(id==='B')return makeRow(id,raw,'motor_b_latest',
   {attempted:nonnegative(r.visited),blocked:Array.isArray(r.errors)?r.errors.length:null,
    candidates:nonnegative(r.ready),queued:nonnegative(r.reviews),processed:nonnegative(r.visited)},
   r.at,['Unidad: documentos/páginas, no fuentes territoriales.']);
 if(id==='C')return makeRow(id,raw,'motor_c_local_latest',
   {attempted:nonnegative(r.visited),blocked:Array.isArray(r.errors)?r.errors.length:null,
    candidates:nonnegative(r.identified),queued:nonnegative(r.queued),processed:nonnegative(r.visited)},
   r.at,['Unidad: documentos y enlaces, no fuentes territoriales.']);
 if(id==='D'){
  const state=String(r.state||'');
  const failure=/error|invalid|unverified|awaiting_read_token/.test(state);
  return makeRow(id,raw,'motor_d_bridge_status',
   {attempted:nonnegative(r.producerSourcesChecked),useful:nonnegative(r.producerSourcesAccessible),
    candidates:nonnegative(r.producerReadyCandidates),publishedConfirmed:null},
   r.producerLastScanAt||r.at,[
    'Fuentes accesibles desde heartbeat; no prueba publicación.',
    state?'Estado del puente: '+state:'Sin estado del puente'
   ],failure);
 }
 if(id==='GEMINI'){
  const state=String(r.state||'');
  return makeRow(id,raw,'gemini_github_pull_status',
   {candidates:nonnegative(r.received),queued:nonnegative(r.queued),publishedConfirmed:null},
   r.at,[state?'Importador: '+state:'Sin registro del productor.',
     'Encolados no son vacantes publicadas; fuentes de Gemini aún sin sincronización.'
   ],/pull_error|github_http_error/.test(state));
 }
 return makeRow(id,raw,'ChatGPT productor no conectado',{},null,
   ['El radar de GitHub todavía no sincroniza una bitácora comparable a AppDeploy.']);
}
export function rollup(rows:EngineRow[]) {
 return {recent:rows.filter(x=>x.status==='recent').length,
  reporting:rows.filter(x=>x.status!=='unreported'&&x.status!=='error').length,
  total:ENGINE_IDS.length};
}

import {secrets} from '@appdeploy/sdk';
import {ENGINE_IDS,asRow,makeRow,nonnegative,stamp,type EngineRow} from './engine-metrics-contract';

/** Source-side producer snapshots. All calls are GET to exact repositories and
 * known report paths; only aggregate counters return to the admin interface.
 * Authenticated GitHub access is server side and never logged or exposed.
 */
const BASE='https://api.github.com/repos/';
const PUBLIC_REPO='mrvvergara-afk/Trabajo-Cerca-';
const GEMINI_REPO='mrvvergara-afk/motor-rastreo-gemini';
const TTL_MS=4*60_000;
let cached:{at:number;rows:Partial<Record<'D'|'CHATGPT'|'GEMINI',EngineRow>>}|null=null;
let flight:Promise<Partial<Record<'D'|'CHATGPT'|'GEMINI',EngineRow>>>|null=null;

function reportDay(offset=0):string {
 const now=new Date(Date.now()-offset*86400_000);
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Santiago',
  year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
 const obj=Object.fromEntries(parts.map(p=>[p.type,p.value]));
 return obj.year+obj.month+obj.day;
}
async function githubJson(repo:string,path:string,token:string|null):Promise<Record<string,unknown>|null> {
 const address=BASE+repo+'/contents/'+path+'?ref=main';
 const headers:Record<string,string>={Accept:'application/vnd.github+json',
  'User-Agent':'TrabajoCerca-AdminBI','X-GitHub-Api-Version':'2022-11-28'};
 if(token)headers.Authorization='Bearer '+token;
 const response=await fetch(address,{headers,redirect:'error',signal:AbortSignal.timeout(5000)});
 if(response.status===404)return null;
 if(!response.ok)return null;
 const file=asRow(await response.json());
 if(file.encoding!=='base64'||typeof file.content!=='string'||
   typeof file.size!=='number'||file.size>900_000)return null;
 const bytes=Buffer.from(file.content.replace(/\s/g,''),'base64');
 if(bytes.byteLength!==file.size)return null;
 const decoded=JSON.parse(bytes.toString('utf8')) as unknown;
 return asRow(decoded);
}
function chatgptRow(report:Record<string,unknown>):EngineRow|null {
 if(report.schema_version!==1)return null;
 const entries=Array.isArray(report.source_results)?report.source_results:[];
 const latest=new Map<string,Record<string,unknown>>();
 for(const raw of entries){
  const x=asRow(raw),key=String(x.source_id||'');
  if(!key)continue;
  const prior=latest.get(key);
  if(!prior||String(x.attempted_at||'')>=String(prior.attempted_at||''))latest.set(key,x);
 }
 const rows=[...latest.values()];
 const checked=rows.filter(x=>['checked_found','checked_empty'].includes(String(x.status))).length;
 const found=rows.filter(x=>x.status==='checked_found').length;
 const blocked=rows.filter(x=>x.status==='blocked').length;
 const attempted=rows.filter(x=>x.status!=='not_attempted'&&x.status!=='unreported').length;
 const scheduled=nonnegative(report.inventory_endpoints);
 const at=stamp(report.run_at);
 if(!at)return null;
 return makeRow('CHATGPT',report,'GitHub: chatgpt_coverage',
  {scheduled,attempted,useful:checked,blocked,candidates:null,
   publishedConfirmed:null},at,[
    'Lectura útil = fuente revisada con estado checked_empty o checked_found.',
    'Detectó resultados en '+found+' índices; no equivale a ofertas publicadas.',
    report.coverage_complete===true?'Inventario declarado como completo':'Cobertura incompleta según productor'
  ]);
}
function motorDRow(report:Record<string,unknown>):EngineRow|null {
 if(report.schema_version!==1||report.producer!=='motor_d_territorial')return null;
 const at=stamp(report.scan_completed_at);if(!at)return null;
 return makeRow('D',report,'GitHub: producer_heartbeat',
  {scheduled:nonnegative(report.source_inventory_registered),
   attempted:nonnegative(report.sources_total),
   useful:nonnegative(report.sources_accessible),
   blocked:nonnegative(report.sources_blocked),
   candidates:nonnegative(report.job_candidates_total),
   publishedConfirmed:report.publication_confirmed===true
     ?nonnegative(report.published_in_trabajo_cerca):null
  },at,[
   'Productor D independiente; 12 comunas son un requisito distinto al 100 % de fuentes.',
   report.full_usable_coverage===true?'Cobertura útil completa acreditada':'Cobertura útil incompleta.'
  ]);
}
function geminiRow(report:Record<string,unknown>):EngineRow|null {
 const at=stamp(report.scanFinishedAt);if(!at)return null;
 return makeRow('GEMINI',report,'GitHub privado: gemini_source_audit_v2',
  {scheduled:nonnegative(report.inventoryExpected),
   attempted:nonnegative(report.sourcesAttempted),
   useful:nonnegative(report.sourcesAccessible),
   blocked:nonnegative(report.sourcesBlocked),
   candidates:nonnegative(report.detailAccepted),
   queued:nonnegative(report.newEntries),
   publishedConfirmed:null
  },at,[
   'Fuentes con enlaces individuales: '+(nonnegative(report.sourcesWithIndividualLinks)??'Sin datos'),
   'Fuentes HTML accesibles sin enlace individual: '+(nonnegative(report.sourcesAccessibleWithoutIndividualLinks)??'Sin datos'),
   'Aceptadas por el productor y encoladas no son publicaciones.'
  ]);
}
async function readLatest():Promise<Partial<Record<'D'|'CHATGPT'|'GEMINI',EngineRow>>>{
 let token:string|null=null;
 try{
  const names=await secrets.listSecretNames();
  if(names.includes('MOTOR_C_GITHUB_READ_TOKEN'))token=await secrets.readSecret('MOTOR_C_GITHUB_READ_TOKEN');
 }catch{/* Public producer files remain accessible; private Gemini stays unknown. */}
 const tasks=await Promise.allSettled([
  githubJson(PUBLIC_REPO,'automation/motor_d_discovery/producer_heartbeat.json',token),
  githubJson(PUBLIC_REPO,'automation/chatgpt_coverage/'+reportDay()+'.json',token),
  token?githubJson(GEMINI_REPO,'output/gemini_source_audit_v2.json',token):Promise.resolve(null)
 ]);
 const result:Partial<Record<'D'|'CHATGPT'|'GEMINI',EngineRow>>={};
 const d=tasks[0].status==='fulfilled'?tasks[0].value:null;
 const c=tasks[1].status==='fulfilled'?tasks[1].value:null;
 const g=tasks[2].status==='fulfilled'?tasks[2].value:null;
 if(d){const row=motorDRow(d);if(row)result.D=row;}
 if(c){const row=chatgptRow(c);if(row)result.CHATGPT=row;}
 if(g){const row=geminiRow(g);if(row)result.GEMINI=row;}
 // Do not silently classify older data as a successful today run.
 return result;
}
export async function producerAudits():Promise<Partial<Record<'D'|'CHATGPT'|'GEMINI',EngineRow>>> {
 if(cached&&Date.now()-cached.at<TTL_MS)return cached.rows;
 if(!flight)flight=readLatest().then(rows=>{cached={at:Date.now(),rows};return rows;})
   .finally(()=>{flight=null;});
 return flight;
}

import {db} from '@appdeploy/sdk';
import {producerAudits} from './engine-source-audit';
import {ENGINE_IDS,adaptEngine,rollup,asRow,nonnegative,stamp,
 type EngineId,type DayPoint,type EngineRow} from './engine-metrics-contract';

/** All reads are bounded. This endpoint has no side effects and is restricted
 * by requireAuth + requireAdminEmailAllowlist in the parent router.
 */
const STATUS_TABLES:Partial<Record<EngineId,[string,string]>>={
 A:['free_public_source_cursor_v3','cursor'],
 B:['motor_b_latest','current'],
 C:['motor_c_local_latest','current'],
 D:['motor_d_bridge_status','current'],
 GEMINI:['gemini_github_pull_status','current']
};
const HISTORIES=[
 {engine:'A',table:'free_public_source_runs',measure:'sources_attempted'},
 {engine:'B',table:'motor_b_runs',measure:'docs_processed'},
 {engine:'C',table:'motor_c_local_runs',measure:'docs_processed'}
] as const;

type ReadOutcome={value:Record<string,unknown>|null;error:boolean};
async function readStatus(table:string,id:string):Promise<ReadOutcome>{
 try {
   const [record]=await db.get<Record<string,unknown>>(table,[id],{consistent:true});
   return {value:record??null,error:false};
 } catch {
   return {value:null,error:true};
 }
}
function dayChile(value:unknown):string|null {
 const iso=stamp(value);if(!iso)return null;
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Santiago',year:'numeric',
  month:'2-digit',day:'2-digit'}).formatToParts(new Date(iso));
 const fields=Object.fromEntries(parts.map(x=>[x.type,x.value]));
 return fields.year&&fields.month&&fields.day?fields.year+'-'+fields.month+'-'+fields.day:null;
}
function runValue(engine:'A'|'B'|'C',row:Record<string,unknown>):number|null {
 if(engine==='A')return nonnegative(asRow(row.summary).sourcesRead);
 return nonnegative(row.visited);
}
function runTime(row:Record<string,unknown>):string|null {
 return stamp(row.at||row.checkedAt||asRow(row.summary).checkedAt);
}
/* Sampled histories: db.list does not guarantee a complete chronological range. */
async function readHistory(engine:'A'|'B'|'C',table:string,measure:DayPoint['measure']){
 try {
   const page=await db.list<Record<string,unknown>>(table,{limit:60});
   const daily=new Map<string,number>(),windowStart=Date.now()-8*86400000;
   for(const item of page.items) {
     const ts=runTime(item);
     if(!ts||Date.parse(ts)<windowStart||Date.parse(ts)>Date.now()+300000)continue;
     const day=dayChile(ts),value=runValue(engine,item);
     if(!day||value===null)continue;
     daily.set(day,(daily.get(day)||0)+value);
   }
   return {points:[...daily].sort((a,b)=>a[0].localeCompare(b[0]))
     .map(([day,value])=>({day,engine,measure,value})),complete:!page.nextToken,error:false};
 } catch {
   return {points:[] as DayPoint[],complete:false,error:true};
 }
}
export async function executiveEngineTelemetry() {
 const statuses=await Promise.all(ENGINE_IDS.map(async id=>{
   const source=STATUS_TABLES[id];
   if(!source)return {id,value:null,error:false};
   const data=await readStatus(source[0],source[1]);
   return {id,...data};
 }));
 const internal:EngineRow[]=statuses.map(item=>
   adaptEngine(item.id,item.value,{readFailed:item.error}));
 // Reporter snapshots are fetched independently from authoritative producer
 // artifacts, not from the import queue; only counters enter the response.
 const [external,histories]=await Promise.all([
   producerAudits().catch(()=>({} as Awaited<ReturnType<typeof producerAudits>>)),
   Promise.all(HISTORIES.map(h=>readHistory(h.engine,h.table,h.measure)))
 ]);
 const engines:EngineRow[]=internal.map(item=>{
   const candidate=item.id==='D'||item.id==='CHATGPT'||item.id==='GEMINI'?external[item.id]:null;
   // A recent direct producer observation supersedes an old importer report.
   if(!candidate)return item;
   if(!item.observedAt)return candidate;
   return Date.parse(candidate.observedAt||'')>=Date.parse(item.observedAt)?candidate:item;
 });
 const points=histories.flatMap(h=>h.points);
 const incomplete=histories.some(x=>!x.complete);
 const missing=engines.filter(x=>x.status==='unreported'||x.status==='error').map(x=>x.id);
 return {
   schemaVersion:1,readOnly:true,
   generatedAt:new Date().toISOString(),
   measurements:{discovery:'fuentes por última ejecución',documents:'documentos/links por última ejecución',
      history:'muestra acotada de hasta 60 ejecuciones por motor; no representa una serie exhaustiva',
      publications:'solo catálogo público confirmado; no atribuibles aún a motor de origen'},
   engines,rollup:rollup(engines),history:points,
   historyComplete:!incomplete,
   missingOrFailed:missing,
   warning:missing.length
     ? 'Algunos productores no entregan telemetría conectada. No sustituir ausencia por cero.'
     : 'Las métricas de producción son por etapa; las publicaciones requieren conciliación con el catálogo.',
   personalDataIncluded:false
 };
}

import { db } from '@appdeploy/sdk';
import { createHash } from 'node:crypto';
import { freePublicSourceStatus, publicDocumentUrl, saveVerifiedPublicOffer } from './free-public-sources';
import { safePublicUrl, publicSourceAdapter } from './public-source-adapters';
import { fetchPublicPage } from './public-source-http';
import { evaluatePublicJob } from './public-source-verifier';
import { bcCheckLimit } from './recheck-policy';

type JobResult={id:string;url:string;checkedAt:string;firstReason:string;decision:string;reason:string;published:boolean;attempts?:number};
const TABLE='fast_bc_html_decisions_v1';
const STATUS='fast_bc_html_status_v1';
const key=(url:string)=>createHash('sha256').update('fast-bc-html:'+url).digest('hex').slice(0,48);
const targetPlaces=new Set(['angol','collipulli','mininco','ercilla','lumaco','los-sauces','puren','renaico','traiguen','victoria','mulchen','negrete','coihue','coigue','nacimiento']);
const nonTargetCities=new Set(['valdivia','chillan','constitucion','santiago','concepcion','temuco','osorno','talca','puerto-montt','san-jose-de-la-mariquina']);
const indexPaths=/\/(?:search|trabaje-con-nosotros|empleos|ofertas-laborales|bolsa-de-empleo)\/?$/i;
function genericSourceIndex(url:string){try{const u=new URL(url);return indexPaths.test(u.pathname) && !u.searchParams.has('id') && !u.searchParams.has('jobId') && !u.searchParams.has('oferta');}catch{return false;}}
// Only the location prefix on Arauco's individual-job URLs is used as a triage hint.
// A non-target prefix is NOT a rejection: the job may describe a different worksite.
function locationHint(url:string){
 try{
  const u=new URL(url);
  if(u.hostname!=='jobs.arauco.com')return 'unknown';
  const slug=decodeURIComponent(u.pathname.split('/')[3]||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if([...targetPlaces].some(city=>slug.startsWith(city+'-')))return 'target';
  if([...nonTargetCities].some(city=>slug.startsWith(city+'-')))return 'outside_hint';
  return 'unknown'; // Unrecognized city is not proof of out-of-territory work.
 }catch{return 'unknown';}
}

export async function runFastBCHtml(){
 const source=await freePublicSourceStatus();
 const reviewed=Array.isArray(source.summary?.reviewed)?source.summary.reviewed as Array<{url?:string;status?:string;reason?:string}>:[];
 // Only the latest Motor A first-pass findings are eligible; never import historical queues.
 const seenUrls=new Set<string>();
 const recheckRows=Array.isArray(source.recheckWork)?source.recheckWork as Array<{url?:string}>:[];
 const reviewedWithRechecks=[...reviewed,...recheckRows.map(row=>({...row,status:'pending',reason:'revalidation_due'}))];
 const todo=reviewedWithRechecks.filter(row=>{
  if(row.status!=='pending' || typeof row.url!=='string' || publicDocumentUrl(row.url))return false;
  const url=safePublicUrl(row.url);
  if(!url || seenUrls.has(url))return false;
  seenUrls.add(url);
  return true;
 });
 // Prioritize territorial candidates; keep outside hints auditable but avoid spending
 // the limited three network checks on obvious out-of-area Arauco URL prefixes.
 todo.sort((a,b)=>Number(locationHint(a.url||'')==='outside_hint')-Number(locationHint(b.url||'')==='outside_hint'));
 let checked=0,verified=0,archived=0,blocked=0,already=0,legacyRecovered=0,deferredOutside=0,deferredIndex=0,storedForFeed=0,storageFailures=0;
 const outcomes:Array<{url:string;decision:string;reason:string}>=[];
 // Walk the entire bounded first-pass result so early already-seen rows cannot starve later ones.
 const checkLimit=bcCheckLimit(todo.length,12);
 for(const row of todo){
  if(checked>=checkLimit)break;
  const url=safePublicUrl(row.url || '');
  if(!url || !publicSourceAdapter(url))continue;
  if(genericSourceIndex(url)){deferredIndex++;continue;}
  if(locationHint(url)==='outside_hint'){deferredOutside++;continue;}
  const id=key(url);
  const [prior]=await db.get<JobResult>(TABLE,[id],{consistent:true});
  // A pending or blocked decision is not a final rejection. Retry at most twice,
  // separated by 24 hours; successful and confirmed-closed decisions stay final.
  if(prior){
   // Legacy decisions archived missing structured data even when the job was still open.
   const legacyFalseArchive=prior.decision==='archived_insufficient_evidence' && !['source_removed','closed_notice','expired_deadline'].includes(prior.reason);
   const retryable=legacyFalseArchive || ['pending_evidence','blocked_source','blocked_verification_storage'].includes(prior.decision);
   const elapsed=Date.now()-Date.parse(prior.checkedAt);
   const maxAttempts=prior.decision==='blocked_verification_storage'?4:prior.decision==='blocked_source'?3:2;
   if(!retryable || (prior.attempts||1)>=maxAttempts || !Number.isFinite(elapsed) || elapsed<24*60*60*1000){already++;continue;}
   if(legacyFalseArchive)legacyRecovered++;
  }
  checked++;
  const page=await fetchPublicPage(url,url);
  const result=page.error?{status:'pending',reason:page.error}:
    evaluatePublicJob(url,page.raw,page.url,page.status,Date.now());
  let decision='pending_evidence',reason=String(result.reason || 'unresolved').slice(0,120),published=false;
  if(result.status==='verified'){
   try{await saveVerifiedPublicOffer(result,Date.now());decision='stored_pending_public_feed';published=false;verified++;storedForFeed++;}
   catch(error){decision='blocked_verification_storage';reason=String(error).slice(0,110);blocked++;storageFailures++;}
  }else if(page.error || [0,401,403,429,500,502,503].includes(page.status)){
   decision='blocked_source';blocked++;
  }else if(result.status==='rejected' && ['source_removed','closed_notice','expired_deadline'].includes(result.reason)){
   decision='confirmed_closed';archived++;
  }
  const record={id,url,firstReason:prior?.firstReason || row.reason || '',checkedAt:new Date().toISOString(),decision,reason,published,attempts:(prior?.attempts||0)+1};
  const [stored]=prior ? await db.tx.update(TABLE,[{id,record}]) : await db.tx.add(TABLE,[record]);
  if(!stored){storageFailures++;console.warn('FAST_B_C_DECISION_WRITE_FAILED '+JSON.stringify({url,decision}));} // Never count failed writes as successful deduplication.
  outcomes.push({url,decision,reason});
 }
 const summary={checkedAt:new Date().toISOString(),aCheckedAt:source.checkedAt,found:todo.length,checked,verified,archived,blocked,already,legacyRecovered,deferredOutside,deferredIndex,storedForFeed,storageFailures,outcomes};
 // Avoid a status write on idle five-minute cron cycles; keep last meaningful result.
 if(checked===0 && storageFailures===0){
  console.warn('FAST_B_C_HTML_IDLE '+JSON.stringify({found:todo.length,already,deferredOutside,deferredIndex}));
  return summary;
 }
 const [old]=await db.get<{id:string}>(STATUS,['current'],{consistent:true});
 if(old)await db.tx.update(STATUS,[{id:'current',record:{id:'current',...summary}}]);
 else await db.tx.add(STATUS,[{id:'current',...summary}]);
 console.warn('FAST_B_C_HTML '+JSON.stringify(summary).slice(0,3600));
 return summary;
}

import { db } from '@appdeploy/sdk';
import { shadowPdfBatch } from './shadow-pdf';
import { runFastBCHtml } from './fast-bc-html';
import { pruneResolved } from './recheck-policy';

/**
 * Dedicated fast B/C third-pass processor. Reads ONLY live Motor A documentWork.
 * It never calls legacy B/C crawlers or queues, and cannot auto-publish an
 * unverifiable PDF. The verified A/D direct route remains untouched.
 */
type Decision={state:'closed'|'not_job'|'needs_source_evidence'|'blocked';reason:string;checkedAt:string};
type Progress={id:string;resolved:Record<string,Decision>;lastRunAt?:string;lastBatch?:Record<string,unknown>};
const STATE='fast_bc_state_v2';
const nonJob= /subsidio electrico|beneficios? estudiantiles|feria|puesto de venta|becas?|decreto municipal/i;
const jobDocumentName=/bases[-_ ].*cargo|bases[-_ ]jefatura|bases[-_ ]profesional|cargo[-_ ].*auxiliar|jefe[-_ ]tecnic|tecnico[-_ ]extensionista|concurso|postul|oferta[-_ ]laboral|operari/i;
export async function runFastBCPipeline(){
  // PDF extraction and short HTML second-chance review run independently.
  const [result,html]=await Promise.all([shadowPdfBatch(),runFastBCHtml()]);
  // No new PDF decisions or HTML work: reuse the checkpoint instead of
  // migrating old rows and writing the same status on every cron invocation.
  if(result.processed===0 && html.checked===0 && html.storageFailures===0){
    const [previous]=await db.get<Progress>(STATE,['current'],{consistent:true});
    if(previous?.lastBatch){
      console.warn('MOTOR_B_C_FAST_IDLE '+JSON.stringify({remainingPdf:result.totalDocuments}));
      return {...previous.lastBatch, idle:true};
    }
  }
  const [existing]=await db.get<Progress>(STATE,['current'],{consistent:true});
  const legacy=(await db.list<Progress>('fast_bc_state_v1',{limit:40})).items;
  const migrated:Record<string,Decision>={};
  for(const row of legacy){for(const [url,decision] of Object.entries(row.resolved || {})){
    const previous=migrated[url];
    if(!previous || Date.parse(decision.checkedAt)>Date.parse(previous.checkedAt))migrated[url]=decision;
  }}
  const resolved:Record<string,Decision>={...migrated,...(existing?.resolved || {})};
  const counted={closed:0,not_job:0,needs_source_evidence:0,blocked:0};
  const now=new Date().toISOString();
  for(const item of result.outcomes){
    const url=String(item.url || '');
    if(!url)continue;
    const stage=String(item.stage || '');
    const titles=Array.isArray(item.jobTitles)?item.jobTitles.map(String):[];
    const reason=String(item.reason || 'without_evidence').slice(0,110);
    // Motor C: definitive triage without a pending retry cycle.
    // Recoverable offers are preserved as evidence, never mistaken for verified jobs.
    const state:Decision['state']=stage==='closed'?'closed':
      stage==='blocked'?'blocked':
      stage==='recoverable'?'needs_source_evidence':
      !nonJob.test(url) && (titles.length>0 || jobDocumentName.test(url))?'needs_source_evidence':'not_job';
    resolved[url]={state,reason,checkedAt:now};
    counted[state]++;
  }
  // A single bounded checkpoint allows A to acknowledge completed documents.
  // No old A/B/C tables are reopened or deleted.
  // Keep unresolved cases until they receive a terminal decision. Dropping
  // them merely because the map is large makes them reappear as new work.
  const pruned=pruneResolved(resolved,1000);
  const record={id:'current',resolved:pruned,lastRunAt:now,
    lastBatch:{scanned:result.processed,remainingPdf:Math.max(0,result.totalDocuments-result.processed),
      decisions:counted,completedTotal:Object.keys(pruned).length,html:{found:html.found,checked:html.checked,verified:html.verified,archived:html.archived,blocked:html.blocked}}};
  if(existing){const [ok]=await db.tx.update(STATE,[{id:'current',record}]);if(!ok)throw Error('fast_bc_checkpoint_update_failed');}
  else{const [id]=await db.tx.add(STATE,[record]);if(!id)throw Error('fast_bc_checkpoint_create_failed');}
  console.warn('MOTOR_B_C_FAST '+JSON.stringify(record.lastBatch));
  return record.lastBatch;
}

