export async function decideAdvertiserLead(ctx:RouterContext){
  const input=ctx.body as {id?:string;status?:string};
  if(!input||typeof input.id!=='string'||!input.id||input.id.length>100||!['new','in_review','rejected'].includes(input.status||''))return error('Decisión comercial inválida.',400);
  const [lead]=await db.get<{status?:string;trialState?:string;trialCampaignId?:string}>('growth_advertiser_leads',[input.id],{consistent:true});
  if(!lead)return error('Solicitud inexistente.',404);
  if(lead.trialCampaignId||lead.trialState==='active'||lead.status==='approved')return error('Esta solicitud ya fue aprobada.',409);
  if(lead.status===input.status)return privateJson({id:input.id,status:input.status,unchanged:true});
  const now=new Date().toISOString();
  try{await db.transact([
    db.tx.update('growth_advertiser_leads',[{id:input.id,record:{status:input.status,trialState:input.status==='rejected'?'rejected':input.status==='in_review'?'in_review':'pending_review',reviewedBy:ctx.user?.userId,reviewedAt:now},if:{status:lead.status}}],{patch:true}),
    db.tx.add('growth_commercial_audit',[{id:randomUUID(),action:'lead_review',leadId:input.id,status:input.status,actor:ctx.user?.userId,at:now}])
  ]);}catch(cause){if(isAppDatabaseError(cause)&&['AppDatabaseConditionFailed','AppDatabaseConflict','AppDatabaseDuplicateId','AppDatabaseUnknownOutcome'].includes(cause.code))return error('La solicitud cambió o la decisión no quedó confirmada. Recarga.',409);throw cause;}
  return privateJson({id:input.id,status:input.status});
}


