 const input=ctx.body as {id?:string;communes?:string[];placements?:string[];plan?:string};
 if(!input||typeof input.id!=='string'||!input.id||input.id.length>150||!['basic','featured','multi'].includes(input.plan||''))return error('Solicitud inválida.',400);
 if(!Array.isArray(input.communes)||!input.communes.length||input.communes.length>14||new Set(input.communes).size!==input.communes.length||input.communes.some(c=>!COMMERCIAL_PLACES.includes(c)))return error('Comunas inválidas.',400);
 if(!Array.isArray(input.placements)||!input.placements.length||new Set(input.placements).size!==input.placements.length||input.placements.some(p=>!['search','listing'].includes(p)))return error('Espacios inválidos.',400);
