 if(!campaign)return error('Campaña no encontrada.',404);
 if(campaign.status==='rejected')return error('Campaña rechazada.',409);
 if(!input.communes.some(c=>!campaign.communes.includes(c))&&!input.placements.some(p=>!(campaign.placements||['search']).includes(p)))return error('Selecciona al menos una comuna o espacio adicional.',400);
 const id='expansion-'+input.id.replace(/[^a-zA-Z0-9-]/g,'').slice(0,70);
