 const [existing]=await db.get('growth_commercial_expansion_requests',[id],{consistent:true});
 if(existing&&existing.status!=='pending_payment_validation')return error('La ampliación anterior está en revisión.',409);
 if(existing)await db.tx.update('growth_commercial_expansion_requests',[{id,record:proposal}]);else await db.tx.add('growth_commercial_expansion_requests',[proposal]);
 return privateJson({saved:true,notice:'Propuesta guardada sin publicar ni cobrar.'});
