export async function activateFreeTrial(ctx:RouterContext) {
  const input=ctx.body as {leadId?:string;headline?:string;detail?:string;url?:string;imageStoragePath?:string;publicWhatsAppApproved?:boolean};
  if(!input||typeof input.leadId!=='string'||input.leadId.length>100||typeof input.headline!=='string'||!input.headline.trim()||input.headline.length>120||typeof input.detail!=='string'||!input.detail.trim()||input.detail.length>300)return error('Completa el anuncio revisado.',400);
  if(input.url){try{const u=new URL(input.url);if(u.protocol!=='https:'||u.username||u.password||u.hostname==='localhost'||!u.hostname.includes('.'))throw Error();}catch{return error('Enlace comercial inválido.',400);}}

  if(input.url?.startsWith('https://wa.me/')&&input.publicWhatsAppApproved!==true)return error('El WhatsApp requiere autorización de publicación confirmada por el administrador.',400);
  if(input.publicWhatsAppApproved&&(!input.url||!/^https:\/\/wa\.me\/569\d{8}$/.test(input.url)))return error('Confirma un número WhatsApp móvil chileno válido.',400);
  if(input.imageStoragePath){
    if(!/^house-creatives\/[a-f0-9]{64}\.(png|jpg|webp)$/.test(input.imageStoragePath))return error('Ruta de imagen inválida.',400);
    const [stored]=await storage.read([input.imageStoragePath]);
    if(!stored?.content)return error('Imagen no encontrada. Vuelve a generarla.',400);
  }

  const [lead]=await db.get('growth_advertiser_leads',[input.leadId],{consistent:true});
  if(!lead)return error('Solicitud no encontrada.',404);
  if(lead.advertisingConsent!==true)return error('La solicitud no acredita autorización publicitaria. No se activa.',409);
  if(lead.status==='rejected')return error('Solicitud rechazada: vuelve a abrirla antes de aprobar.',409);
  if(!COMMERCIAL_PLACES.includes(lead.commune))return error('Comuna fuera de cobertura comercial.',400);
  if(!businessIdentity(String(lead.businessName||'')))return error('Identifica el negocio.',400);
  const key=digest(businessIdentity(lead.businessName));
  // Excepción de laboratorio solo para el negocio de prueba solicitado.
  // No modifica el calendario de lanzamiento ni activa promociones de otros negocios.
  const isMinincoPilot = lead.commune === 'Mininco' &&
    businessIdentity(String(lead.businessName || '')) === 'ferreteriamininco';
  const campaignId='trial-'+digest(input.leadId);
  const reconcile=async()=>{
    const [receipt]=await db.get('growth_trial_entitlements',[key],{consistent:true});
    if(!receipt)return null;
    return receipt.leadId===input.leadId?privateJson({id:receipt.campaignId,duplicate:true,startAt:receipt.startAt,endAt:receipt.endAt,promotion:receipt.promotion}):error('Este negocio ya recibió su promoción gratuita. No son acumulables.',409);
  };
  const prior=await reconcile();if(prior)return prior;
  // Protect legacy trials from being renewed through the new programme.
  const [existing]=await db.get('growth_campaigns',[campaignId],{consistent:true});
  if(existing)return privateJson({id:campaignId,duplicate:true,startAt:existing.startAt,endAt:existing.endAt});
  const legacy=(await commercialInventory()).some(ad=>(ad.adType==='COMMERCIAL_FREE'||ad.id.startsWith('trial-'))&&businessIdentity(ad.businessName)===businessIdentity(lead.businessName));
  if(legacy)return error('El negocio ya tiene una promoción histórica; requiere revisión, no otra prueba gratuita.',409);
  for(let attempt=0;attempt<3;attempt++){
    const config = await commercialConfiguration();
    const standardOffer = promotionOffer(config);
    const pilotMode = isMinincoPilot &&
      (!standardOffer.days || config.revision === 'commercial-defaults-v1');
    // El piloto tiene exactamente 30 días y no consume cupos de fundadores.
    const offer = pilotMode
      ? {kind:'laboratorio', days:30}
      : standardOffer;
    if (!offer.days || (!pilotMode && config.revision === 'commercial-defaults-v1')) {
      return error('Configura y aprueba explícitamente el lanzamiento antes de activar promociones.',409);
    }
    const startAt=new Date().toISOString();const endAt=new Date(Date.parse(startAt)+offer.days*86400000).toISOString();
    const record={id:campaignId,advertiserId:key,promotion:offer.kind,adType:'COMMERCIAL_FREE',...(pilotMode?{labPilot:true}:{}),businessName:lead.businessName,category:lead.category,communes:[lead.commune],headline:input.headline.trim(),detail:input.detail.trim(),url:input.url||undefined,...(input.imageStoragePath?{image:{storagePath:input.imageStoragePath,approved:true,reviewedAt:startAt}}:{}),startAt,endAt,status:'active',label:'Publicidad local',priority:0,placements:['search'],createdAt:startAt};
    try{
      await db.transact([
        db.tx.add('growth_trial_entitlements',[{id:key,leadId:input.leadId,campaignId,startAt,endAt,promotion:offer.kind,days:offer.days,createdAt:startAt}]),
        db.tx.add('growth_campaigns',[record]),
        db.tx.update('growth_advertiser_leads',[{id:input.leadId,record:{advertiserId:key,trialCampaignId:campaignId,trialState:'active',status:'approved',reviewedAt:startAt,reviewedBy:ctx.user?.userId,trialStartAt:startAt,trialEndAt:endAt,promotion:offer.kind},if:{trialCampaignId:undefined,status:lead.status}}],{patch:true}),
        // Sin cambio global de configuración ni cupos para la prueba acotada.
        ...(pilotMode ? [] : [
          db.tx.update('growth_commercial_config', [{
            id:'current',
            record:{foundersUsed:config.foundersUsed+(offer.kind==='founder'?1:0)},
            if:{revision:config.revision,foundersUsed:config.foundersUsed}
          }],{patch:true})
        ]),
        db.tx.add('growth_commercial_audit',[{id:randomUUID(),action:'trial_approved',campaignId,actor:ctx.user?.userId,promotion:offer.kind,at:startAt}]),
      ]);
    }catch(cause){
      if(isAppDatabaseError(cause)&&['AppDatabaseDuplicateId','AppDatabaseConditionFailed','AppDatabaseConflict','AppDatabaseUnknownOutcome'].includes(cause.code)){
        const recovered=await reconcile();if(recovered)return recovered;
        if(cause.code==='AppDatabaseUnknownOutcome')return error('Resultado pendiente de confirmación. Comprueba antes de repetir.',409);
        continue;
      }throw cause;
    }
    invalidateCommercialInventory();await houseConversion(lead.houseAttribution,'trial_activated',campaignId);
    return privateJson({id:campaignId,startAt,endAt,promotion:offer.kind,days:offer.days},201);
  }
  return error('Otra aprobación está en curso; recarga y vuelve a comprobar.',409);
}

/** Bounded, deterministic rotation. A source must not endlessly re-read its first page. */
export function rotateIndex<T>(items:ReadonlyArray<T>, limit:number, attempts:number) {
  if (!Number.isSafeInteger(limit) || limit<1 || limit>1000) throw new Error('invalid_index_limit');
  if (!Number.isSafeInteger(attempts) || attempts<0) throw new Error('invalid_index_attempt');
  const total=items.length;
  const offset=total ? (attempts*limit)%total : 0;
  const selected:T[]=[];
  for(let index=0;index<Math.min(limit,total);index++){
    selected.push(items[(offset+index)%total]);
  }
  return {items:selected,total,offset,partial:total>limit};
}

