  ]);
  const state = stateRows.items[0];
  if (!state?.lastRunAt) {
    await writeSingleRecord('notification_dispatch_state', { lastRunAt:nowIso, updatedAt:nowIso });
    return { initialized:true, offers:0, matchedUsers:0, sent:0, failed:0 };
  }
  const since = Date.parse(state.lastRunAt);
  const eligible = [...radarRows.items, ...communityRows.items]
    .filter(item => item.kind === 'job_offer' && item.verified && !item.review && isCurrentlyActive(item))
    .filter(item => {
      const publishedTs = parseDiscoveryDate(item.sourcePublishedAt || item.date);
      if (!publishedTs || staleDiscoveryDate(new Date(publishedTs).toISOString())) return false;
      const becamePublic = Date.parse(item.firstVerifiedAt || item.verifiedAt || item.createdAt);
      return Number.isFinite(becamePublic) && becamePublic > since && becamePublic <= now.getTime();
    });
  let matchedUsers = 0;
  let sent = 0;
  let failed = 0;
  for (const pref of prefsRows.items.filter(item => item.active)) {
    const matches = eligible.filter(item => notificationPreferenceMatches(item, pref));
    if (!matches.length) continue;
    matchedUsers += 1;
    const first = matches[0];
    const primaryPlace = pref.communes.find(place => matches.some(item => item.workCommunes.includes(place))) || first.workCommunes[0] || pref.communes[0];
    const title = matches.length === 1 ? `Nueva oferta en ${primaryPlace}` : `${matches.length} nuevas ofertas en tu zona`;
    const body = matches.length === 1 ? `${first.title} · ${first.company}` : `${first.title} y ${matches.length - 1} más. Todas verificadas por Trabajo Cerca.`;
    try {
      const result = await notifications.send({
        userIds:[pref.userId],
        notification:{ title, body, url:`/?place=${encodeURIComponent(primaryPlace)}&new=1` },
        data:{ kind:'new_verified_jobs', count:String(matches.length), commune:primaryPlace },
        ttlSeconds:43200,
      });
      sent += result.sent;
      failed += result.failed;
    } catch { failed += 1; }
  }
  await writeSingleRecord('notification_dispatch_state', { lastRunAt:nowIso, updatedAt:nowIso });
  if (eligible.length || matchedUsers) await db.add('notification_dispatch_log', [{ checkedAt:nowIso, offers:eligible.length, matchedUsers, sent, failed }]);
  return { initialized:false, offers:eligible.length, matchedUsers, sent, failed };
}

function projectFeedListing(value:Record<string, unknown> & { id:string }) {
  const item=value as unknown as ListingRecord & { id:string };
  if (item.kind!=='job_offer') return isCurrentlyActive(item) ? publicRecord(item) : null;
  if (offerRetentionReason(value)) return null;
  // An internal social review horizon is not evidence that applications closed.
  // Keep verified notices visible until an explicit source deadline or confirmed closure.
  if (publicJobExclusion(value)) return null;
  // Trabajo Cerca covers exactly 12 communes; never expose neighboring hubs from automatic review.
  const projectionPlaces = PILOT;
  const locationScope=[...(item.workCommunes||[]),...(value.territorialRecruitmentVerified===true?item.recruitmentCommunes||[]:[])];
  if (!locationScope.some(commune=>projectionPlaces.some(target=>normalizeText(target).toLocaleLowerCase('es-CL')===normalizeText(commune).toLocaleLowerCase('es-CL')))) return null;
  const evidence=[item.title,item.company,item.note,item.url,item.sourceDomain].filter(Boolean).join(' ');
  if (unsafeContentReason(evidence,item.url)) return null;
  const primaryDate=parseDiscoveryDate(item.sourcePublishedAt || item.date);
  const firstKnown=Date.parse(String(value.firstPublishedAt||''));
  // First verified appearance supports retention but is NEVER the source date.
  const eligibilityDate=primaryDate ?? (item.verified===true && Number.isFinite(firstKnown)?firstKnown:undefined);
  if(!eligibilityDate||eligibilityDate>Date.now())return null;
  const publishedItem={...publicRecord(item),...(primaryDate?{}:{sourceDateUnconfirmed:true})};
  // Correct only cases with a named work commune in the source title/URL.
  // Keep one public record per offer, even if it applies to several communes.
  const sourceText=String(item.title||'')+' '+String(item.url||'');
  const corrections:Array<{sourceId:string;commune:string;explicitTitle:boolean}>=[
    {sourceId:'3891310',commune:'Traiguén',explicitTitle:true},
    {sourceId:'3891189',commune:'Traiguén',explicitTitle:true},
    {sourceId:'3889603',commune:'Nacimiento',explicitTitle:true},
    {sourceId:'3894935',commune:'Mulchén',explicitTitle:false}
  ];
  const correction=corrections.find(entry=>sourceText.includes(entry.sourceId));
  if(correction && (!correction.explicitTitle || normalizeText(String(item.title||'')).toLowerCase().includes(normalizeText(correction.commune).toLowerCase()))) {
    const existing=Array.isArray(item.workCommunes)?item.workCommunes:[];
    const localWorkCommunes=[...new Set([...existing,correction.commune])];
    return {...publishedItem,workCommunes:localWorkCommunes,
      territorialCorrection:'explicit_worksite_in_source',
      firstPublishedAt:knownFirstPublication(value),revalidationDue:offerRecheckDue(value)};
  }
  return { ...publishedItem,firstPublishedAt:knownFirstPublication(value),revalidationDue:offerRecheckDue(value) };
}

function feedRefreshAt(item:Record<string, unknown>) {
  const now=Date.now(),deadline=confirmedOfferDeadline(item);
  const candidates:number[]=[];
  if (deadline!==null) candidates.push(deadline+1);
  // Internal review horizon for undated official OMIL notices, not a source closing date.
  if (item.validityMethod==='municipal_open_status') {
    const evidenceUntil=Date.parse(String(item.municipalOpenEvidenceValidUntil||''));
    if (Number.isFinite(evidenceUntil)) candidates.push(evidenceUntil+1);
  }
  if(item.validityMethod==='verified_open_official_source'){
    const evidenceUntil=Date.parse(String(item.openOfficialEvidenceValidUntil||''));
    if(Number.isFinite(evidenceUntil))candidates.push(evidenceUntil+1);
  }
  // Legacy internalVisibilityUntil is a review reminder, never a visibility deadline.
  const checked=Date.parse(String(item.lastVerifiedAt || item.externalVerifiedAt || item.verifiedAt || ''));
  if (Number.isFinite(checked)) candidates.push(checked+86400000+1);
  const first=Date.parse(String(item.firstPublishedAt || item.createdAt || ''));
  if (Number.isFinite(first)) candidates.push(first+86400000+1,first+7*86400000+1);
  const upcoming=candidates.filter(time=>Number.isFinite(time)&&time>now);
  return upcoming.length ? Math.min(...upcoming) : null;
}

