// Repair missed projections without overriding verification, closure or territorial checks.
async function reconcileEligiblePublicGaps() {
  const knownIds=new Set<string>(),knownUrls=new Set<string>();
  let cursor:string|undefined,publicComplete=false;
  for(let step=0;step<100;step++){
    const page=await readPublicFeedPage(cursor);
    if(!page)return {state:'feed_unavailable',queued:0};
    for(const row of (page.items||[]) as Array<Record<string,unknown>>){
      knownIds.add(String(row.id||''));
      if(typeof row.url==='string'){
        const key=publicFeedIdentity(row.url);
        if(key)knownUrls.add(key);
      }
    }
    if(!page.nextCursor){publicComplete=true;break;}
    cursor=page.nextCursor;
  }
  if(!publicComplete)return {state:'feed_incomplete',queued:0};
  // Existing queue may already contain valid changes; don't inflate it.
  const pending=new Set<string>();let queueCursor:string|undefined;
  for(let step=0;step<10;step++){
    const page=await db.list<{source:string;sourceId:string}>('public_feed_changes',{limit:100,...(queueCursor?{nextToken:queueCursor}:{})});
    for(const change of page.items)if(change.source==='radar_jobs')pending.add(change.sourceId);
    if(!page.nextToken)break;
    queueCursor=page.nextToken;
  }
  const queuedIds:string[]=[];let sourceCursor:string|undefined,scanned=0,eligibleMissing=0;
  const diagnostic:Record<string,number>={published:0,duplicateEquivalent:0,expiredExplicit:0,inactive:0,requiresVerification:0,originRequired:0,missingOriginalUrl:0,territoryMismatch:0,unsafe:0,missingOriginalDate:0,otherProjectionBlock:0,eligibleAbsent:0,queuedAlready:0};
  const communeDiagnostics:Record<string,{records:number;published:number;pending:number;blocked:number;eligibleAbsent:number}>={};
  const countCommunes=(row:Record<string,unknown>,key:'records'|'published'|'pending'|'blocked'|'eligibleAbsent')=>{
    for(const city of (Array.isArray(row.workCommunes)?row.workCommunes:[])){
      if(typeof city!=='string')continue;
      const stats=communeDiagnostics[city]||(communeDiagnostics[city]={records:0,published:0,pending:0,blocked:0,eligibleAbsent:0});
      stats[key]++;
    }
  };
  for(let step=0;step<15;step++){
    const page=await db.list<Record<string,unknown>>('radar_jobs',{limit:100,...(sourceCursor?{nextToken:sourceCursor}:{})});
    for(const row of page.items){
      if(row.kind!=='job_offer')continue;
      scanned++;countCommunes(row,'records');
      const id=String(row.id||'');
      if(!id)continue;
      if(knownIds.has(id)){diagnostic.published++;countCommunes(row,'published');continue;}
      const key=typeof row.url==='string'?publicFeedIdentity(row.url):null;
      if(key&&knownUrls.has(key)){diagnostic.duplicateEquivalent++;countCommunes(row,'published');continue;}
      const explicitDeadline=Date.parse(String(row.sourceValidThrough||''));
      if(Number.isFinite(explicitDeadline)&&explicitDeadline<Date.now()){diagnostic.expiredExplicit++;continue;}
      if(row.active!==true){diagnostic.inactive++;continue;}
      if(row.verified!==true||row.review===true){diagnostic.requiresVerification++;countCommunes(row,'pending');continue;}
      const retention=offerRetentionReason(row);
      if(retention){diagnostic.otherProjectionBlock++;countCommunes(row,'blocked');continue;}
      const exclusion=publicJobExclusion(row);
      if(exclusion){
        if(exclusion==='aggregator_requires_primary_source'||exclusion==='portal_index_not_individual_offer')diagnostic.originRequired++;
        else if(exclusion==='original_individual_url_missing')diagnostic.missingOriginalUrl++;
        else diagnostic.otherProjectionBlock++;
        countCommunes(row,'blocked');continue;
      }
      const work=Array.isArray(row.workCommunes)?row.workCommunes:[];
      const allowed=(row.secondaryMarket===true&&row.discoveredBy==='free-public-sources-v1')?MARKET_PLACES:PILOT;
      if(!work.some(place=>allowed.some(target=>normalizeText(target).toLocaleLowerCase('es-CL')===normalizeText(String(place)).toLocaleLowerCase('es-CL')))){
        diagnostic.territoryMismatch++;countCommunes(row,'blocked');continue;
      }
      const evidence=[row.title,row.company,row.note,row.url,row.sourceDomain].filter(Boolean).join(' ');
      if(unsafeContentReason(evidence,typeof row.url==='string'?row.url:undefined)){diagnostic.unsafe++;countCommunes(row,'blocked');continue;}
      const originalDate=parseDiscoveryDate(String(row.sourcePublishedAt||row.date||''));
      if(!originalDate||originalDate>Date.now()){diagnostic.missingOriginalDate++;countCommunes(row,'blocked');continue;}
      // Exactly the same publication decision as the authoritative projection.
      if(!projectFeedListing(row as Record<string,unknown>&{id:string})){diagnostic.otherProjectionBlock++;countCommunes(row,'blocked');continue;}
      diagnostic.eligibleAbsent++;countCommunes(row,'eligibleAbsent');
      eligibleMissing++;
      if(pending.has(id)){diagnostic.queuedAlready++;continue;}
      if(queuedIds.length<12){
        await registerPublicFeedChange('radar_jobs',id);
        pending.add(id);queuedIds.push(id);
      }
    }
    if(!page.nextToken)break;
    sourceCursor=page.nextToken;
  }
  const result={state:'checked',scanned,eligibleMissing,queued:queuedIds.length,queuedIds,diagnostic,communes:communeDiagnostics,checkedAt:new Date().toISOString()};
  await writeSingleRecord('radar_gap_recovery_last',result);
  return result;
}

// Incremental, auditable archival. Never delete original records or evidence.
// Only a source-supplied, explicit application deadline is definitive.
async function archiveConfirmedClosedJobs(){
  const current=await db.list<RadarPageCursor>('radar_verified_archive_cursor',{limit:1});
  const page=await db.list<ListingRecord>('radar_jobs',{limit:100,...(current.items[0]?.nextToken?{nextToken:current.items[0].nextToken}:{})});
  const now=Date.now(),updates:Array<{id:string;record:Record<string,unknown>}>=[];
  let inspected=0,missingDeadline=0;
  for(const item of page.items){
    if(item.kind!=='job_offer'||item.active!==true)continue;
    inspected++;
    const explicit=Date.parse(String(item.sourceValidThrough||''));
    if(!Number.isFinite(explicit)){missingDeadline++;continue;}
    if(explicit>=now)continue;
    if(updates.length>=25)continue;
    const {id,...original}=item;
    updates.push({id,record:{...original,active:false,review:false,
      status:'Archivada · plazo cerrado',archiveReason:'explicit_application_deadline_elapsed',
      archiveEvidence:{field:'sourceValidThrough',value:item.sourceValidThrough,
        sourceUrl:item.url||null,checkedAt:new Date(now).toISOString()},
      archivedAt:new Date(now).toISOString()}});
  }
  if(updates.length){
    const saved=await trackedFeedUpdate('radar_jobs',updates);
    if(saved.length!==updates.length||saved.some(ok=>!ok))throw new Error('Archived jobs not fully saved; preserve cursor');
  }
  await saveRadarPageCursor('radar_verified_archive_cursor',current.items[0],page.nextToken);
  const summary={checkedAt:new Date(now).toISOString(),inspected,archived:updates.length,
