export const v14VerificationHandler = async (event?:{ type:string; name:string; scheduledTime:string }) => {
  // Historical review queues are frozen. A and D register verified offers directly.
  const documents={status:'legacy_document_rechecks_frozen'};
  const documentError:unknown=undefined;
  const providerSlot=false;
  const history={status:'legacy_backlog_frozen'};
  const result={processed:0,verified:0,rejected:0,kept:0,status:'legacy_backlog_frozen'};
  // Archive confirmed closures in the existing publisher cron, before the feed is advanced.
  if(event?.type==='cron'&&event.name==='verify-publish'&&new Date(event.scheduledTime).getUTCMinutes()===35){
    try{console.warn('RADAR_ARCHIVE '+JSON.stringify(await archiveConfirmedClosedJobs()));}
    catch(cause){console.warn('RADAR_ARCHIVE_ERROR '+String(cause).slice(0,200));}
  }
  const ingestion={stored:0,published:0,status:'legacy_signed_pull_frozen'};
  // The D bridge processes one durable batch every publisher run.
  if(event?.type==='cron' && event.name==='verify-publish'){
    try { await motorDAutoImportHandler(); }
    catch(cause){console.warn('MOTOR_D_BRIDGE_HOOK_ERROR '+String(cause).slice(0,150));}
    try { await chatgptAutoImportHandler(); }
    catch(cause){console.warn('CHATGPT_BRIDGE_HOOK_ERROR '+String(cause).slice(0,150));}
    try { await repairApprovedTerritoriesOnce(); }
    catch(cause){console.warn('WORKSITE_SAFE_REPAIR_ERROR '+String(cause).slice(0,180));}
    // One-time verified duplicate correction, before updating the public feed.
    try { await archiveMislocatedCmpcDuplicateOnce(); }
    catch(cause){console.warn('CMPC_DUPLICATE_REPAIR_ERROR '+String(cause).slice(0,180));}
    // Verified municipal open notices renew daily. A confirmed CLOSED index
    // removes them; a blocked source does not masquerade as closure.
    try { console.warn('MOTOR_D_MUNICIPAL_RECHECK '+JSON.stringify(
      await revalidateOfficialMunicipalOpenOffers())); }
    catch(cause){console.warn('MOTOR_D_MUNICIPAL_RECHECK_ERROR '+String(cause).slice(0,170));}
  }
  const administrative=isAdminVerificationSlot(event) ? await processAdminReviewBatch({scheduledTime:event!.scheduledTime,project:projectFeedListing}) : undefined;
  const feedProjector={ revision:'published-retention-counts-v8-location', reconcileManifestId:'a7425daf-c460-4d88-98fc-adfae0b807fd', project:projectFeedListing, refreshAt:feedRefreshAt };
  // Resume the backlog hourly until cleared; when clean, perform only a daily
  // safety reconciliation. New/changed offers already use trackedFeedAdd/Update.
  // Previous backlog gap reconciliation must not requeue archived historical offers.
  let feed=await advancePublicFeed(feedProjector);
  // Finish up to four bounded startup steps per verification invocation.
  // Do not repeatedly reproject an already available public snapshot.
  for(let step=1;step<4 && feed.rebuilding===true;step++) feed=await advancePublicFeed(feedProjector);
  const receipts={status:'legacy_receipts_frozen',published:0};
  const motorDConfirm=await confirmMotorDPublications();
  console.warn('MOTOR_D_PUBLICATION_CONFIRM '+JSON.stringify(motorDConfirm));
  const chatgptConfirm=await confirmChatGPTPublications();
  console.warn('CHATGPT_PUBLICATION_CONFIRM '+JSON.stringify(chatgptConfirm));
  const adminPublications=isAdminVerificationSlot(event) ? await confirmAdminReviewPublications() : undefined;
  console.warn('RADAR_VERIFY_HISTORY '+JSON.stringify({documents,providerSlot,history,result,ingestion,receipts,administrative,adminPublications,publicJobs:feed.totalVerifiedJobOffers,feedRebuilding:feed.rebuilding}));
  if (documentError) throw documentError;
  return {statusCode:200};
};
